import {
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from 'react';
import { IconArrowsVertical } from '../../../icons/arrows-vertical';
import { IconClose } from '../../../icons/close';
import { IconEnterKey } from '../../../icons/enter-key';
import { IconSearch } from '../../../icons/search';
import { announce } from '../../../primitives/announce';
import { useControllableState } from '../../../primitives/use-controllable-state';
import { matchItem } from './fuzzy';
import './command-palette.css';

export interface CommandItem {
  id: string;
  label: string;
  /** Items with the same group are listed under one heading, in first-seen order. */
  group?: string;
  /** Extra words that should find this item, such as synonyms. */
  keywords?: readonly string[];
  /** Short text on the right, such as a location or a shortcut. */
  hint?: string;
  icon?: ReactNode;
  disabled?: boolean;
}

export interface CommandPaletteProps {
  items: readonly CommandItem[];
  onSelect: (item: CommandItem) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Accessible name of the dialog. */
  label?: string;
  placeholder?: string;
  /** Item ids shown first under "Recent" while the query is empty. */
  recentIds?: readonly string[];
  /** Global shortcut that toggles the palette, like `Mod+K`. `null` turns it off. */
  hotkey?: string | null;
  /** Also open with `/` when focus is not in a text field. */
  slashOpens?: boolean;
  /** Shown when nothing matches. */
  emptyMessage?: (query: string) => ReactNode;
  maxResults?: number;
}

interface Row {
  item: CommandItem;
  group: string;
  indices: number[];
}

const RECENT = 'Recent';
const UNGROUPED = 'Results';

function matchesHotkey(event: globalThis.KeyboardEvent, hotkey: string): boolean {
  const parts = hotkey.split('+').map((p) => p.trim().toLowerCase());
  const key = parts.pop();
  const mac = /mac|iphone|ipad/i.test(navigator.platform || navigator.userAgent);
  const wantsMod = parts.includes('mod');
  const mod = mac ? event.metaKey : event.ctrlKey;
  if (wantsMod !== mod) return false;
  if (parts.includes('shift') !== event.shiftKey) return false;
  if (parts.includes('alt') !== event.altKey) return false;
  return event.key.toLowerCase() === key;
}

function isEditable(target: EventTarget | null): boolean {
  return (
    target instanceof HTMLElement &&
    (target.isContentEditable || /^(input|textarea|select)$/i.test(target.tagName))
  );
}

function Highlight({ text, indices }: { text: string; indices: number[] }) {
  if (indices.length === 0) return <>{text}</>;
  const marked = new Set(indices);
  const parts: ReactNode[] = [];
  let run = '';
  let runMarked = false;
  const flush = (key: number) => {
    if (!run) return;
    parts.push(runMarked ? <mark key={key}>{run}</mark> : run);
    run = '';
  };
  for (let i = 0; i < text.length; i++) {
    const isMarked = marked.has(i);
    if (isMarked !== runMarked) {
      flush(i);
      runMarked = isMarked;
    }
    run += text[i];
  }
  flush(text.length);
  return <>{parts}</>;
}

export function CommandPalette({
  items,
  onSelect,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  label = 'Command palette',
  placeholder = 'Search or jump to…',
  recentIds = [],
  hotkey = 'Mod+K',
  slashOpens = false,
  emptyMessage = (query) => <>Nothing matches “{query}”. Try a shorter word, or a category name.</>,
  maxResults = 60,
}: CommandPaletteProps) {
  const [open, setOpen] = useControllableState({
    value: openProp,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);
  const dialogRef = useRef<HTMLDialogElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const returnFocus = useRef<HTMLElement | null>(null);
  const baseId = useId();
  const listId = `${baseId}-list`;

  const rows = useMemo<Row[]>(() => {
    const trimmed = query.trim();
    if (!trimmed) {
      const byId = new Map(items.map((item) => [item.id, item]));
      const recent = recentIds
        .map((id) => byId.get(id))
        .filter((item): item is CommandItem => Boolean(item))
        .map((item) => ({ item, group: RECENT, indices: [] }));
      const recentSet = new Set(recent.map((r) => r.item.id));
      const rest = items
        .filter((item) => !recentSet.has(item.id))
        .map((item) => ({ item, group: item.group ?? UNGROUPED, indices: [] }));
      return [...recent, ...rest].slice(0, maxResults);
    }
    return items
      .map((item, order) => ({ item, order, match: matchItem(trimmed, item) }))
      .filter((r) => r.match !== null)
      .sort((a, b) => b.match!.score - a.match!.score || a.order - b.order)
      .slice(0, maxResults)
      .map((r) => ({ item: r.item, group: r.item.group ?? UNGROUPED, indices: r.match!.indices }));
  }, [items, query, recentIds, maxResults]);

  // Group in first-seen order while keeping the rank order inside each group.
  const groups = useMemo(() => {
    const map = new Map<string, Row[]>();
    for (const row of rows) {
      const list = map.get(row.group) ?? [];
      list.push(row);
      map.set(row.group, list);
    }
    return [...map.entries()];
  }, [rows]);

  const flat = useMemo(() => groups.flatMap(([, list]) => list), [groups]);
  const enabled = flat.filter((row) => !row.item.disabled);
  const activeRow = enabled[Math.min(active, enabled.length - 1)];
  const optionId = (id: string) => `${baseId}-opt-${id.replace(/[^\w-]/g, '_')}`;

  // Open and close the native modal dialog to match state.
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    if (open && !dialog.open) {
      returnFocus.current = document.activeElement as HTMLElement | null;
      setQuery('');
      setActive(0);
      dialog.showModal();
      inputRef.current?.focus();
    } else if (!open && dialog.open) {
      dialog.close();
      const target = returnFocus.current;
      if (target?.isConnected) target.focus({ preventScroll: true });
    }
  }, [open]);

  // Global shortcut.
  useEffect(() => {
    if (!hotkey && !slashOpens) return;
    const onKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.defaultPrevented) return;
      if (hotkey && matchesHotkey(event, hotkey)) {
        event.preventDefault();
        setOpen((value) => !value);
      } else if (slashOpens && event.key === '/' && !isEditable(event.target)) {
        event.preventDefault();
        setOpen(true);
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [hotkey, slashOpens, setOpen]);

  // Keep the active option in view.
  useEffect(() => {
    if (!activeRow) return;
    document.getElementById(optionId(activeRow.item.id))?.scrollIntoView({ block: 'nearest' });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeRow?.item.id]);

  // Announce the result count once typing pauses.
  useEffect(() => {
    if (!open || !query.trim()) return;
    const timer = window.setTimeout(() => {
      announce(
        enabled.length === 0
          ? 'No results'
          : `${enabled.length} result${enabled.length === 1 ? '' : 's'}`,
      );
    }, 450);
    return () => window.clearTimeout(timer);
  }, [open, query, enabled.length]);

  const choose = (row: Row | undefined) => {
    if (!row || row.item.disabled) return;
    setOpen(false);
    onSelect(row.item);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    const count = enabled.length;
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        if (count) setActive((i) => (Math.min(i, count - 1) + 1) % count);
        break;
      case 'ArrowUp':
        event.preventDefault();
        if (count) setActive((i) => (Math.min(i, count - 1) - 1 + count) % count);
        break;
      case 'Enter':
        event.preventDefault();
        choose(activeRow);
        break;
      case 'Escape':
        // Handled here rather than by the dialog, so the first Escape can clear the query
        // and outer listeners see the event as consumed.
        event.preventDefault();
        if (query) {
          setQuery('');
          setActive(0);
        } else setOpen(false);
        break;
    }
  };

  let optionIndex = -1;

  return (
    // Backdrop clicks are a pointer convenience; keyboard users close with Escape or the Close button.
    // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions
    <dialog
      ref={dialogRef}
      className="atl-palette"
      aria-label={label}
      onCancel={(event) => {
        event.preventDefault();
        setOpen(false);
      }}
      onClick={(event) => {
        // A click on the dialog element itself (not its content) is a click on the backdrop.
        if (event.target === event.currentTarget) setOpen(false);
      }}
    >
      <div className="atl-palette__panel">
        <div className="atl-palette__field">
          <IconSearch className="atl-palette__glass" size={22} />
          <input
            ref={inputRef}
            className="atl-palette__input"
            role="combobox"
            aria-label={label}
            aria-expanded="true"
            aria-controls={listId}
            aria-autocomplete="list"
            aria-activedescendant={activeRow ? optionId(activeRow.item.id) : undefined}
            autoComplete="off"
            autoCorrect="off"
            spellCheck={false}
            placeholder={placeholder}
            value={query}
            onChange={(event) => {
              setQuery(event.target.value);
              setActive(0);
            }}
            onKeyDown={onKeyDown}
          />
          <button
            type="button"
            className="atl-palette__close"
            aria-label="Close"
            onClick={() => setOpen(false)}
          >
            <IconClose size={18} />
          </button>
        </div>

        <div
          ref={listRef}
          className="atl-palette__list"
          id={listId}
          role="listbox"
          aria-label="Results"
        >
          {groups.map(([group, list]) => {
            const headingId = `${baseId}-group-${group.replace(/[^\w-]/g, '_')}`;
            return (
              <div
                key={group}
                role="group"
                aria-labelledby={headingId}
                className="atl-palette__group"
              >
                <div id={headingId} role="presentation" className="atl-palette__heading">
                  {group}
                </div>
                {list.map((row) => {
                  const disabled = Boolean(row.item.disabled);
                  if (!disabled) optionIndex += 1;
                  const index = optionIndex;
                  const isActive = !disabled && activeRow?.item.id === row.item.id;
                  return (
                    // Options are reached from the input through aria-activedescendant, so they take
                    // no focus or key handlers of their own (WAI-ARIA combobox pattern).
                    // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/interactive-supports-focus
                    <div
                      key={row.item.id}
                      id={optionId(row.item.id)}
                      role="option"
                      aria-selected={isActive}
                      aria-disabled={disabled || undefined}
                      className="atl-palette__option"
                      onPointerMove={() => {
                        if (!disabled && !isActive) setActive(index);
                      }}
                      onClick={() => choose(row)}
                    >
                      {row.item.icon ? (
                        <span className="atl-palette__icon" aria-hidden="true">
                          {row.item.icon}
                        </span>
                      ) : null}
                      <span className="atl-palette__label">
                        <Highlight text={row.item.label} indices={row.indices} />
                      </span>
                      {row.item.hint ? (
                        <span className="atl-palette__hint">{row.item.hint}</span>
                      ) : null}
                    </div>
                  );
                })}
              </div>
            );
          })}
          {flat.length === 0 ? (
            <p className="atl-palette__empty">{emptyMessage(query.trim())}</p>
          ) : null}
        </div>

        <div className="atl-palette__footer" aria-hidden="true">
          <span>
            <kbd>
              <IconArrowsVertical size={14} />
            </kbd>{' '}
            move
          </span>
          <span>
            <kbd>
              <IconEnterKey size={14} />
            </kbd>{' '}
            open
          </span>
          <span>
            <kbd>Esc</kbd> {query ? 'clear' : 'close'}
          </span>
        </div>
      </div>
    </dialog>
  );
}

export interface FuzzyResult {
  score: number;
  /** Indices in the text that matched, for highlighting. */
  indices: number[];
}

const WORD_START = 8;
const FIRST_CHAR = 4;
const CONSECUTIVE = 7;
const MATCH = 1;
const GAP = 0.6;
const GAP_OPEN = 3;
const PREFIX = 12;

function isWordStart(text: string, index: number): boolean {
  if (index === 0) return true;
  const previous = text[index - 1] ?? '';
  const current = text[index] ?? '';
  if (/[\s\-_./:(]/.test(previous)) return true;
  return previous === previous.toLowerCase() && current !== current.toLowerCase();
}

/**
 * Scores how well `query` matches `text` as an in-order subsequence. Prefers matches at
 * word starts and in consecutive runs, and penalises gaps. Dynamic programming finds the
 * best alignment, not just the first one. Returns null when some character is missing.
 */
export function fuzzyScore(query: string, text: string): FuzzyResult | null {
  const q = query.toLowerCase();
  const t = text.toLowerCase();
  const m = q.length;
  const n = t.length;
  if (m === 0) return { score: 0, indices: [] };
  if (m > n) return null;

  // score[i][j]: best score for q[0..i] with q[i] matched at t[j]; from[i][j]: where q[i-1] sat.
  const score: Float64Array[] = [];
  const from: Int32Array[] = [];
  for (let i = 0; i < m; i++) {
    score.push(new Float64Array(n).fill(-Infinity));
    from.push(new Int32Array(n).fill(-1));
  }

  for (let j = 0; j < n; j++) {
    if (t[j] !== q[0]) continue;
    let s = MATCH;
    if (isWordStart(text, j)) s += WORD_START;
    if (j === 0) s += FIRST_CHAR;
    score[0]![j] = s - j * 0.1;
  }

  for (let i = 1; i < m; i++) {
    let best = -Infinity;
    let bestAt = -1;
    for (let j = i; j < n; j++) {
      // best[k] for k < j - 1, with the gap penalty applied as we move right
      const previous = score[i - 1]![j - 1]!;
      if (best !== -Infinity) best -= GAP;
      if (t[j] === q[i]) {
        let s = -Infinity;
        let at = -1;
        if (previous !== -Infinity) {
          s = previous + MATCH + CONSECUTIVE;
          at = j - 1;
        }
        if (best !== -Infinity) {
          const gapped = best - GAP_OPEN + MATCH + (isWordStart(text, j) ? WORD_START : 0);
          if (gapped > s) {
            s = gapped;
            at = bestAt;
          }
        }
        score[i]![j] = s;
        from[i]![j] = at;
      }
      if (previous > best) {
        best = previous;
        bestAt = j - 1;
      }
    }
  }

  let end = -1;
  let total = -Infinity;
  for (let j = 0; j < n; j++) {
    if (score[m - 1]![j]! > total) {
      total = score[m - 1]![j]!;
      end = j;
    }
  }
  if (end === -1) return null;

  const indices: number[] = [];
  for (let i = m - 1, j = end; i >= 0 && j >= 0; i--) {
    indices.unshift(j);
    j = from[i]![j]!;
  }
  if (t.startsWith(q)) total += PREFIX;
  return { score: total, indices };
}

export interface SearchableItem {
  label: string;
  keywords?: readonly string[] | undefined;
}

/**
 * Matches a whole query against an item. Each space-separated word must match the label
 * or one of the keywords; keyword matches count for less and are not highlighted.
 */
export function matchItem(query: string, item: SearchableItem): FuzzyResult | null {
  const words = query.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return { score: 0, indices: [] };
  let total = 0;
  const indices = new Set<number>();
  for (const word of words) {
    const onLabel = fuzzyScore(word, item.label);
    let best = onLabel ? onLabel.score : -Infinity;
    for (const keyword of item.keywords ?? []) {
      const onKeyword = fuzzyScore(word, keyword);
      if (onKeyword && onKeyword.score * 0.6 > best) best = onKeyword.score * 0.6;
    }
    if (best === -Infinity) return null;
    total += best;
    if (onLabel && onLabel.score >= best) onLabel.indices.forEach((i) => indices.add(i));
  }
  return { score: total, indices: [...indices].sort((a, b) => a - b) };
}

@layer atlas.components {
  .atl-palette {
    --atl-palette-width: 40rem;
    width: min(var(--atl-palette-width), calc(100% - 2 * var(--space-m)));
    max-width: none;
    max-height: min(34rem, calc(100dvh - 2 * var(--space-xl)));
    margin: max(8dvh, var(--space-m)) auto auto;
    padding: 0;
    border: 0;
    border-radius: var(--radius-overlay);
    background: var(--shoal);
    color: var(--ink);
    box-shadow: var(--elev-overlay);
    overflow: hidden;
    opacity: 1;
    translate: 0 0;
    scale: 1;
    transition:
      opacity var(--dur-glide) var(--ease-anchor),
      translate var(--dur-glide) var(--ease-anchor),
      scale var(--dur-glide) var(--ease-anchor),
      overlay var(--dur-glide) allow-discrete,
      display var(--dur-glide) allow-discrete;
  }

  .atl-palette:not([open]) {
    opacity: 0;
    translate: 0 -6px;
    scale: 0.985;
    transition-timing-function: var(--ease-ebb);
    transition-duration: var(--dur-step);
  }

  @starting-style {
    .atl-palette[open] {
      opacity: 0;
      translate: 0 -10px;
      scale: 0.985;
    }
  }

  .atl-palette::backdrop {
    background: rgb(4 12 18 / 0.5);
    background: color-mix(in oklch, var(--sea-3) 62%, transparent);
    transition:
      opacity var(--dur-glide) var(--ease-anchor),
      overlay var(--dur-glide) allow-discrete,
      display var(--dur-glide) allow-discrete;
  }

  .atl-palette:not([open])::backdrop {
    opacity: 0;
  }

  @starting-style {
    .atl-palette[open]::backdrop {
      opacity: 0;
    }
  }

  .atl-palette__panel {
    display: flex;
    flex-direction: column;
    max-height: inherit;
  }

  .atl-palette__field {
    display: flex;
    align-items: center;
    gap: var(--space-s);
    padding: var(--space-xs) var(--space-xs) var(--space-xs) var(--space-m);
    box-shadow: inset 0 -1px 0 color-mix(in oklch, var(--isobath) 70%, transparent);
  }

  .atl-palette__glass {
    flex: none;
    color: var(--ink-soft);
  }

  .atl-palette__input {
    flex: 1;
    min-width: 0;
    min-height: 3.25rem;
    border: 0;
    background: none;
    font-size: var(--step-1);
    font-weight: 450;
    letter-spacing: -0.005em;
  }

  .atl-palette__input::placeholder {
    color: var(--ink-soft);
    opacity: 1;
  }

  .atl-palette__input:focus-visible {
    outline: none;
  }

  /* The field carries focus for the whole palette, so the ring goes on the field row. */
  .atl-palette__field:has(.atl-palette__input:focus-visible) {
    box-shadow:
      inset 0 -1px 0 color-mix(in oklch, var(--isobath) 70%, transparent),
      inset 0 -3px 0 -1px var(--chart-magenta);
  }

  .atl-palette__close {
    display: grid;
    place-items: center;
    flex: none;
    width: var(--target-comfort);
    height: var(--target-comfort);
    border: 0;
    border-radius: var(--radius-control);
    background: none;
    color: var(--ink-soft);
  }

  .atl-palette__close:hover {
    background: var(--ink-wash);
    color: var(--ink);
  }

  .atl-palette__list {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: var(--space-2xs) var(--space-xs) var(--space-xs);
    scroll-padding-block: var(--space-xl) var(--space-xs);
  }

  .atl-palette__group + .atl-palette__group {
    margin-top: var(--space-2xs);
  }

  /* Hydrographic lettering: group names in italic serif, as charts name bodies of water. */
  .atl-palette__heading {
    position: sticky;
    top: calc(-1 * var(--space-2xs));
    z-index: 1;
    padding: var(--space-xs) var(--space-s) var(--space-2xs);
    background: var(--shoal);
    color: var(--ink-soft);
    font-family: var(--font-prose);
    font-style: italic;
    font-size: var(--step-0);
    letter-spacing: 0.01em;
  }

  .atl-palette__option {
    display: flex;
    align-items: center;
    gap: var(--space-s);
    min-height: var(--target-comfort);
    padding: var(--space-2xs) var(--space-s);
    border-radius: var(--radius-control);
    cursor: pointer;
    user-select: none;
  }

  .atl-palette__option[aria-selected='true'] {
    background: var(--reef);
    box-shadow: inset 3px 0 0 var(--chart-magenta);
  }

  .atl-palette__option[aria-disabled='true'] {
    cursor: not-allowed;
    color: var(--ink-soft);
  }

  .atl-palette__icon {
    display: grid;
    place-items: center;
    flex: none;
    color: var(--ink-soft);
  }

  .atl-palette__option[aria-selected='true'] .atl-palette__icon {
    color: var(--ink);
  }

  .atl-palette__label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .atl-palette__label mark {
    background: none;
    color: inherit;
    font-weight: 700;
    text-decoration: underline;
    text-decoration-color: var(--chart-magenta);
    text-decoration-thickness: 2px;
    text-underline-offset: 0.18em;
  }

  .atl-palette__hint {
    flex: none;
    color: var(--ink-soft);
    font-size: var(--step--1);
  }

  .atl-palette__empty {
    padding: var(--space-l) var(--space-s);
    color: var(--ink-soft);
    font-family: var(--font-prose);
    font-size: var(--step-0);
    max-width: var(--measure);
  }

  .atl-palette__footer {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-m);
    padding: var(--space-xs) var(--space-m);
    color: var(--ink-soft);
    font-size: var(--step--1);
    box-shadow: inset 0 1px 0 color-mix(in oklch, var(--isobath) 55%, transparent);
  }

  .atl-palette__footer kbd {
    display: inline-grid;
    place-items: center;
    vertical-align: middle;
    min-height: 1.5em;
  }

  @media (pointer: coarse) {
    .atl-palette__footer {
      display: none;
    }
  }

  @media (forced-colors: active) {
    .atl-palette {
      border: 1px solid CanvasText;
    }
    .atl-palette__option[aria-selected='true'] {
      outline: 2px solid Highlight;
    }
  }
